class _TimeDeltaField(ma.fields.TimeDelta):
    def _deserialize(self, value, *args, **kwargs) -> timedelta:
        """Deserialize value into a timedelta object.

        Supports both ISO 8601 format and a custom format with units:
        - Xw for weeks
        - Xd for days
        - Xh for hours
        - Xm for minutes
        - Xs for seconds
        - Xms for milliseconds
        - X(u|µ)s for microseconds

        Where X is an integer value.
        """
        if isinstance(value, timedelta):
            return value

        try:
            # First try the parent class's deserialization (handles ISO 8601)
            return super()._deserialize(value, *args, **kwargs)
        except ValueError:
            # If that fails, try our custom format
            match = _TIMEDELTA_PATTERN.match(str(value))
            if not match:
                raise ma.ValidationError("Not a valid timedelta.")

            # Extract values from regex groups
            weeks, days, hours, minutes, seconds, milliseconds, microseconds = match.groups()

            # Convert all values to integers, defaulting to 0 if None
            params = {}
            if weeks is not None:
                params['weeks'] = int(weeks)
            if days is not None:
                params['days'] = int(days)
            if hours is not None:
                params['hours'] = int(hours)
            if minutes is not None:
                params['minutes'] = int(minutes)
            if seconds is not None:
                params['seconds'] = int(seconds)
            if milliseconds is not None:
                params['milliseconds'] = int(milliseconds)
            if microseconds is not None:
                params['microseconds'] = int(microseconds)

            if not params:  # If no values were extracted
                raise ma.ValidationError("Not a valid timedelta.")

            return timedelta(**params)

